fullText:
*{
    line-height: 2;
}
header,footer{
    background-image: url(files/ground.jpg);
    background-repeat: no-repeat;
    background-size: cover;
    height: 100px;
}
#logo{
    height: 100px;
}
h1{
    color: aqua;
    display: inline-block;
    transition:4s transform;
}
h1:hover{
    transform:translate(500px,0);
    color: chocolate;
}
main{
    display: flex;
    justify-content: space-between;
    line-height: 4px;
    height: 500px;
    background-image: url(files/bg1.png);
    background-repeat: no-repeat;
    background-size: cover;
}
iframe{
    width: 100%;
    height: 100%;
}
nav{
    width: 30%;
}
section{
    width: 70%;
}
li{
    list-style: none;
    color: rgb(33, 120, 126);
    text-decoration: none;
}
#ajout{
    text-decoration: none;
    color: rgb(33, 120, 126);

}
fieldset{
    display: inline-block;
    justify-content: center;
    border-radius: 0px 20px 0px 20px;
    background-image: url(files/ground.jpg);
    width: 400px;
    height: 400px;
    text-align: center;
}
.supp{
    width: 300px;
    height: 350px;
    justify-content: center;
}
legend{
    font-family: Georgia, 'Times New Roman', Times, serif;
    text-shadow: 3px 3px rgb(222, 212, 212) ;
    color: aqua;
    font-size: larger;
    text-align: left;
}
.input{
    width: 80%;
    border-radius: 20px;
    line-height: 20px;
    padding: 5px;
    margin: 5px;
    text-align: center;
    
}
::placeholder{
    text-align: center;
}
.element{
    color: aliceblue;
    font-size: larger;
    
}
.bt{
    background-color: black;
    color: white;
    width: 80%;
    border-radius: 20px;
    padding: 1px;
    margin: 3px;
}
p{
    color: cyan;
    font-family: cursive;
}

